1	/** Shared cost-item constants (#213). The universal money catalog. */
2	export const COST_ITEM_SELECT =
3	  "id, org_id, event_id, name, amount_cents, category, included_in_trip_cost, linked_option_id, source_type, source_id, sort_order, notes, created_at, updated_at";
4	
5	/** Categories a manual cost item can be filed under (auto items set their own). */
6	export const COST_CATEGORIES = ["lodging", "food", "shirts", "operational", "pass_through", "other"] as const;
7	
8	/** Display labels for both manual categories and the auto source types. */
9	export const COST_CATEGORY_LABEL: Record<string, string> = {
10	  contest: "Contests", side_game: "Side games", lodging: "Lodging", food: "Food",
11	  shirts: "Shirts", operational: "Operational", pass_through: "Pass-through", other: "Other",
12	};
13

1	/**
2	 * v2 contests (#209, Phase 2a) — shared helpers over the contest spine.
3	 *
4	 * A contest is the interactive backing for an `kind='activity'` schedule item
5	 * (scramble first) or a side game hanging off one (skins, CTP, LD, LP), or an
6	 * event-spanning aggregate (BSPITW, 100 Feet!). This module owns the create /
7	 * find-or-create / auto-enroll plumbing; scoring lives in per-type scorers.
8	 */
9	
10	import type { SupabaseClient } from "@supabase/supabase-js";
11	
12	export const CONTEST_TYPES = [
13	  "scramble", "skins", "ctp", "long_drive", "long_putt",
14	  "bspitw", "hundred_feet", "ryder_cup", "calcutta", "cornhole", "pickem", "other",
15	] as const;
16	export type ContestType = (typeof CONTEST_TYPES)[number];
17	
18	export const CONTEST_SELECT =
19	  "id, org_id, event_id, parent_contest_id, contest_type, name, scoring_source, holes, contest_date, start_time, course_id, tee_id, config, payout_splits, auto_enroll, declared_no_winner, status, winners_locked_at, winners_locked_by, sort_order, created_by, created_at, updated_at";
20	
21	export interface Contest {
22	  id: string;
23	  org_id: string;
24	  event_id: string;
25	  parent_contest_id: string | null;
26	  contest_type: ContestType;
27	  name: string;
28	  scoring_source: "derived" | "manual";
29	  holes: number[] | null;
30	  contest_date: string | null;
31	  start_time: string | null;
32	  course_id: string | null;
33	  tee_id: string | null;
34	  config: Record<string, unknown> | null;
35	  payout_splits: unknown;
36	  auto_enroll: boolean;
37	  declared_no_winner: boolean;
38	  status: "draft" | "active" | "final";
39	  winners_locked_at: string | null;
40	  winners_locked_by: string | null;
41	  sort_order: number;
42	  created_by: string | null;
43	  created_at: string;
44	  updated_at: string;
45	}
46	
47	/** Default name when the caller doesn't supply one. */
48	const TYPE_LABEL: Record<string, string> = {
49	  scramble: "Scramble", skins: "Skins", ctp: "Closest to the Pin",
50	  long_drive: "Long Drive", long_putt: "Long Putt", bspitw: "BSPITW",
51	  hundred_feet: "100 Feet!", ryder_cup: "Ryder Cup", calcutta: "Calcutta",
52	  cornhole: "Cornhole", pickem: "Pick'em", other: "Contest",
53	};
54	
55	/** Derived contests read scores/observations; the rest are hand-adjudicated. */
56	export function defaultScoringSource(type: ContestType): "derived" | "manual" {
57	  return type === "scramble" || type === "skins" || type === "bspitw" ? "derived" : "manual";
58	}
59	
60	/** These enroll every on-roster member automatically; the rest are opt-in. */
61	export function defaultAutoEnroll(type: ContestType): boolean {
62	  return type === "scramble" || type === "ryder_cup" || type === "calcutta";
63	}
64	
65	export interface CreateContestInput {
66	  orgId: string;
67	  eventId: string;
68	  contestType: ContestType;
69	  name?: string;
70	  parentContestId?: string | null; // set for side games (child of a scramble)
71	  contestDate?: string | null;      // the day it's played (drives its calendar entry)
72	  startTime?: string | null;        // HH:MM start; seeds the first tee time
73	  holes?: number[] | null;
74	  config?: Record<string, unknown> | null;
75	  entryAmountCents?: number | null;
76	  autoEnroll?: boolean;
77	  createdBy?: string | null;
78	}
79	
80	/**
81	 * Create a contest. Contests are authored here (Contests page), not on the
82	 * schedule — the calendar derives an entry from `contest_date`. Auto-enrolls the
83	 * on-roster set for enrolling types (scramble/ryder/calcutta).
84	 */
85	export async function createContest(
86	  admin: SupabaseClient,
87	  input: CreateContestInput,
88	): Promise<{ contest: Contest } | { error: string }> {
89	  const { data, error } = await admin
90	    .from("v2_contests")
91	    .insert({
92	      org_id: input.orgId,
93	      event_id: input.eventId,
94	      parent_contest_id: input.parentContestId ?? null,
95	      contest_type: input.contestType,
96	      name: (input.name || "").trim() || TYPE_LABEL[input.contestType] || "Contest",
97	      scoring_source: defaultScoringSource(input.contestType),
98	      holes: input.holes ?? null,
99	      contest_date: input.contestDate ?? null,
100	      start_time: input.startTime ?? null,
101	      config: input.config ?? null,
102	      auto_enroll: input.autoEnroll ?? defaultAutoEnroll(input.contestType),
103	      created_by: input.createdBy ?? null,
104	    })
105	    .select(CONTEST_SELECT)
106	    .single();
107	  if (error) return { error: error.message };
108	  const contest = data as Contest;
109	  if (contest.auto_enroll) await autoEnrollFromRoster(admin, contest.id, input.eventId);
110	  await setContestBuyIn(admin, contest, input.entryAmountCents ?? null);
111	  return { contest };
112	}
113	
114	/**
115	 * The buy-in cost item for a contest/side game (#213). The AMOUNT lives only
116	 * here — v2_cost_items is the single source of truth; the contest's buy-in field
117	 * reads/writes this row. `cents` is authoritative:
118	 *   - a positive number → upsert (sets amount; keeps the reconciliation flags)
119	 *   - 0 or null         → delete the row (no buy-in)
120	 *   - undefined         → leave the amount alone, only re-sync the display name
121	 *                         (used when editing a contest's name/date, not its buy-in)
122	 * The cost item's name mirrors the contest name (a display label, not money).
123	 */
124	export async function setContestBuyIn(admin: SupabaseClient, contest: Contest, cents: number | null | undefined): Promise<void> {
125	  const sourceType = contest.parent_contest_id ? "side_game" : "contest";
126	  const { data: existing } = await admin
127	    .from("v2_cost_items").select("id").eq("source_type", sourceType).eq("source_id", contest.id).maybeSingle();
128	
129	  if (cents === undefined) {
130	    if (existing) await admin.from("v2_cost_items").update({ name: contest.name, updated_at: new Date().toISOString() }).eq("id", existing.id);
131	    return;
132	  }
133	  if (!cents || cents <= 0) {
134	    if (existing) await admin.from("v2_cost_items").delete().eq("id", existing.id);
135	    return;
136	  }
137	  if (existing) {
138	    await admin.from("v2_cost_items").update({ name: contest.name, amount_cents: cents, updated_at: new Date().toISOString() }).eq("id", existing.id);
139	  } else {
140	    await admin.from("v2_cost_items").insert({
141	      org_id: contest.org_id, event_id: contest.event_id, name: contest.name, amount_cents: cents,
142	      category: sourceType, source_type: sourceType, source_id: contest.id, created_by: contest.created_by,
143	    });
144	  }
145	}
146	
147	/** Buy-in amounts (cents) for a set of contests/side games, keyed by contest id. */
148	export async function loadBuyInCents(admin: SupabaseClient, contestIds: string[]): Promise<Map<string, number>> {
149	  const out = new Map<string, number>();
150	  if (!contestIds.length) return out;
151	  const { data } = await admin
152	    .from("v2_cost_items").select("source_id, amount_cents")
153	    .in("source_type", ["contest", "side_game"]).in("source_id", contestIds);
154	  for (const r of data || []) if (r.source_id) out.set(r.source_id as string, r.amount_cents as number);
155	  return out;
156	}
157	
158	/** Remove the cost_items projected from a contest and its descendants (on delete). */
159	export async function deleteContestCostItems(admin: SupabaseClient, contestId: string): Promise<void> {
160	  const { data: children } = await admin.from("v2_contests").select("id").eq("parent_contest_id", contestId);
161	  const ids = [contestId, ...(children || []).map((c) => c.id as string)];
162	  await admin.from("v2_cost_items").delete().in("source_id", ids);
163	}
164	
165	/**
166	 * Seed a contest's participants from the event roster (on_roster members) that
167	 * aren't already in it. Additive only — never removes anyone (removal is guarded
168	 * elsewhere). Returns the number added.
169	 */
170	export async function autoEnrollFromRoster(
171	  admin: SupabaseClient,
172	  contestId: string,
173	  eventId: string,
174	): Promise<number> {
175	  const { data: roster } = await admin
176	    .from("v2_event_participants")
177	    .select("user_id")
178	    .eq("event_id", eventId)
179	    .eq("on_roster", true);
180	  const rosterIds = (roster || []).map((r) => r.user_id as string);
181	  if (rosterIds.length === 0) return 0;
182	
183	  const { data: existing } = await admin
184	    .from("v2_contest_participants")
185	    .select("user_id")
186	    .eq("contest_id", contestId);
187	  const have = new Set((existing || []).map((r) => r.user_id as string));
188	
189	  const toAdd = rosterIds.filter((id) => !have.has(id)).map((user_id) => ({ contest_id: contestId, user_id }));
190	  if (toAdd.length === 0) return 0;
191	  const { error } = await admin.from("v2_contest_participants").insert(toAdd);
192	  if (error) return 0;
193	  return toAdd.length;
194	}
