1	import Link from "next/link";
2	import { redirect } from "next/navigation";
3	import { getPlatformContext } from "@/lib/v2/context";
4	import { v2AdminClient } from "@/lib/v2/supabase";
5	import { COST_ITEM_SELECT, COST_CATEGORY_LABEL } from "@/lib/v2/cost-items";
6	import FinancialsManager, { type CostItem } from "./FinancialsManager";
7	import styles from "@/app/new/new.module.css";
8	
9	/**
10	 * Event financials (#213). The reviewable, editable catalog of every cost item,
11	 * reconciled to the Trip Cost or (later) an option. Owner/admin only; the
12	 * breakdown is never shown to regular members.
13	 */
14	export default async function FinancialsPage({ params }: { params: Promise<{ slug: string; eventId: string }> }) {
15	  const { slug, eventId } = await params;
16	  const ctx = await getPlatformContext();
17	  if (!ctx) redirect("/new/signup");
18	  const org = ctx.orgs.find((o) => o.slug === slug);
19	  if (!org || (org.role !== "owner" && org.role !== "admin")) redirect(`/new/${slug}`);
20	
21	  const admin = v2AdminClient();
22	  const [{ data: event }, { data: items }, { data: contestRows }] = await Promise.all([
23	    admin.from("v2_events").select("id, name").eq("id", eventId).eq("org_id", org.id).maybeSingle(),
24	    admin.from("v2_cost_items").select(COST_ITEM_SELECT).eq("event_id", eventId).order("sort_order").order("created_at"),
25	    admin.from("v2_contests").select("id, name, parent_contest_id").eq("event_id", eventId),
26	  ]);
27	  if (!event) redirect(`/new/${slug}/admin`);
28	
29	  // Group contest-sourced items under their top-level contest (a side game lands
30	  // with its parent scramble); everything else groups by its category.
31	  const cmap = new Map((contestRows || []).map((c) => [c.id as string, { name: c.name as string, parent: (c.parent_contest_id as string) ?? null }]));
32	  type CostRow = Omit<CostItem, "group_key" | "group_label">;
33	  const withGroups: CostItem[] = (((items as CostRow[]) || [])).map((it) => {
34	    if (it.source_type === "contest" || it.source_type === "side_game") {
35	      const rec = it.source_id ? cmap.get(it.source_id) : null;
36	      const topId = it.source_type === "side_game" && rec?.parent ? rec.parent : it.source_id;
37	      const top = topId ? cmap.get(topId) : null;
38	      return { ...it, group_key: `contest:${topId}`, group_label: top?.name || "Contest" };
39	    }
40	    const cat = it.category || "other";
41	    return { ...it, group_key: `cat:${cat}`, group_label: COST_CATEGORY_LABEL[cat] || cat };
42	  });
43	
44	  return (
45	    <div className={styles.page}>
46	      <Link href={`/new/${slug}/admin/events/${eventId}`} className={styles.back}>
47	        <svg width="16" height="16" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
48	          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.8} d="M15 19l-7-7 7-7" />
49	        </svg>
50	        {event.name}
51	      </Link>
52	      <div className={styles.titleRow}>
53	        <h1 className={styles.title}>Financials</h1>
54	      </div>
55	
56	      <FinancialsManager slug={slug} orgId={org.id} eventId={eventId} initialItems={withGroups} />
57	    </div>
58	  );
59	}
