1	"use client";
2	
3	import { useMemo, useState } from "react";
4	import Link from "next/link";
5	import { useRouter } from "next/navigation";
6	import {
7	  DndContext, closestCenter, PointerSensor, TouchSensor, useSensor, useSensors, type DragEndEvent,
8	} from "@dnd-kit/core";
9	import { SortableContext, useSortable, verticalListSortingStrategy, arrayMove } from "@dnd-kit/sortable";
10	import { CSS } from "@dnd-kit/utilities";
11	import Modal from "@/app/new/_components/Modal";
12	import ConfirmModal from "@/app/new/_components/ConfirmModal";
13	import { COST_CATEGORIES, COST_CATEGORY_LABEL } from "@/lib/v2/cost-items";
14	import styles from "@/app/new/new.module.css";
15	
16	export interface CostItem {
17	  id: string;
18	  name: string;
19	  amount_cents: number;
20	  category: string | null;
21	  included_in_trip_cost: boolean;
22	  linked_option_id: string | null;
23	  source_type: string;
24	  source_id: string | null;
25	  notes: string | null;
26	  sort_order: number;
27	  // Resolved on the server: which group this item lands in (a contest or a category).
28	  group_key: string;
29	  group_label: string;
30	}
31	
32	const CATEGORIES = COST_CATEGORIES;
33	const CATEGORY_LABEL = COST_CATEGORY_LABEL;
34	
35	// Order within a group: admin's manual order (sort_order) wins; then the contest's
36	// own buy-in before its side games before anything else; alphabetical as the tiebreak.
37	function rowRank(i: CostItem): number {
38	  return i.source_type === "contest" ? 0 : i.source_type === "side_game" ? 1 : 2;
39	}
40	function sortInGroup(a: CostItem, b: CostItem): number {
41	  return a.sort_order - b.sort_order || rowRank(a) - rowRank(b) || a.name.localeCompare(b.name);
42	}
43	
44	function dollars(cents: number): string {
45	  return `$${(cents / 100).toLocaleString("en-US", { minimumFractionDigits: cents % 100 === 0 ? 0 : 2, maximumFractionDigits: 2 })}`;
46	}
47	
48	/**
49	 * The event's cost catalog (#213). Add/edit/delete manual items, reconcile each to
50	 * the Trip Cost, and see the rolled-up totals. Auto items (contest/side-game
51	 * buy-ins) appear read-only here once phase 2 wires them in.
52	 */
53	export default function FinancialsManager({ slug, orgId, eventId, initialItems }: { slug: string; orgId: string; eventId: string; initialItems: CostItem[] }) {
54	  const router = useRouter();
55	  const [items, setItems] = useState<CostItem[]>(initialItems);
56	  const [formFor, setFormFor] = useState<CostItem | "new" | null>(null);
57	  const [confirmDel, setConfirmDel] = useState<CostItem | null>(null);
58	  const [busy, setBusy] = useState(false);
59	  const [error, setError] = useState<string | null>(null);
60	
61	  const [name, setName] = useState("");
62	  const [amount, setAmount] = useState("");
63	  const [category, setCategory] = useState("other");
64	  const [inTrip, setInTrip] = useState(true);
65	
66	  const base = `/api/v2/orgs/${orgId}/events/${eventId}/cost-items`;
67	
68	  const sensors = useSensors(
69	    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
70	    useSensor(TouchSensor, { activationConstraint: { delay: 150, tolerance: 5 } }),
71	  );
72	
73	  const tripTotal = useMemo(() => items.filter((i) => i.included_in_trip_cost).reduce((s, i) => s + i.amount_cents, 0), [items]);
74	  const grandTotal = useMemo(() => items.reduce((s, i) => s + i.amount_cents, 0), [items]);
75	  const groups = useMemo(() => {
76	    const byKey = new Map<string, { label: string; list: CostItem[] }>();
77	    for (const i of items) {
78	      const g = byKey.get(i.group_key) || byKey.set(i.group_key, { label: i.group_label, list: [] }).get(i.group_key)!;
79	      g.list.push(i);
80	    }
81	    for (const g of byKey.values()) g.list.sort(sortInGroup);
82	    // Contest groups first, then category groups; alphabetical by label within each.
83	    return [...byKey.entries()].sort((a, b) => {
84	      const ac = a[0].startsWith("contest:") ? 0 : 1;
85	      const bc = b[0].startsWith("contest:") ? 0 : 1;
86	      return ac - bc || a[1].label.localeCompare(b[1].label);
87	    });
88	  }, [items]);
89	
90	  // New/edited manual items get their category group client-side; auto items keep
91	  // the group the server resolved (carried from the row being replaced).
92	  function applyGroup(fresh: CostItem, prev?: CostItem): CostItem {
93	    if (fresh.source_type !== "manual" && prev) return { ...fresh, group_key: prev.group_key, group_label: prev.group_label };
94	    const cat = fresh.category || "other";
95	    return { ...fresh, group_key: `cat:${cat}`, group_label: CATEGORY_LABEL[cat] || cat };
96	  }
97	
98	  function openAdd() { setName(""); setAmount(""); setCategory("other"); setInTrip(true); setError(null); setFormFor("new"); }
99	  function openEdit(i: CostItem) {
100	    setName(i.name); setAmount((i.amount_cents / 100).toString()); setCategory(i.category || "other"); setInTrip(i.included_in_trip_cost); setError(null); setFormFor(i);
101	  }
102	
103	  async function submit(e: React.FormEvent) {
104	    e.preventDefault();
105	    if (busy || formFor == null) return;
106	    if (!name.trim()) { setError("Name is required"); return; }
107	    setBusy(true); setError(null);
108	    const editingAuto = formFor !== "new" && formFor.source_type !== "manual";
109	    // New items land at the end of their (category) group.
110	    const nextSort = formFor === "new"
111	      ? items.filter((i) => i.group_key === `cat:${category}`).reduce((m, i) => Math.max(m, i.sort_order), -1) + 1
112	      : undefined;
113	    // Auto items (contest buy-ins): only amount + reconciliation are owned here;
114	    // name/category mirror the contest and are left alone.
115	    const payload = editingAuto
116	      ? { amount_cents: amount.trim() ? Math.round(parseFloat(amount) * 100) : 0, included_in_trip_cost: inTrip }
117	      : {
118	          name: name.trim(),
119	          amount_cents: amount.trim() ? Math.round(parseFloat(amount) * 100) : 0,
120	          category,
121	          included_in_trip_cost: inTrip,
122	          ...(nextSort !== undefined ? { sort_order: nextSort } : {}),
123	        };
124	    const res = formFor === "new"
125	      ? await fetch(base, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) })
126	      : await fetch(`${base}/${formFor.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
127	    setBusy(false);
128	    if (!res.ok) { setError((await res.json().catch(() => ({}))).error || "Could not save"); return; }
129	    const { item } = await res.json();
130	    setItems((prev) => (formFor === "new"
131	      ? [...prev, applyGroup(item)]
132	      : prev.map((x) => (x.id === item.id ? applyGroup(item, x) : x))));
133	    setFormFor(null);
134	  }
135	
136	  // Auto items (contest buy-ins) are edited at their source, but their
137	  // reconciliation (in/out of Trip Cost) is set here.
138	  async function toggleTrip(i: CostItem) {
139	    if (busy) return;
140	    setBusy(true);
141	    const res = await fetch(`${base}/${i.id}`, {
142	      method: "PATCH", headers: { "Content-Type": "application/json" },
143	      body: JSON.stringify({ included_in_trip_cost: !i.included_in_trip_cost }),
144	    });
145	    setBusy(false);
146	    if (res.ok) { const { item } = await res.json(); setItems((prev) => prev.map((x) => (x.id === item.id ? applyGroup(item, x) : x))); }
147	    else setError((await res.json().catch(() => ({}))).error || "Could not update");
148	  }
149	
150	  // Reorder within a single group (never across groups — each group is its own
151	  // DndContext). Assigns sequential sort_order and persists only what moved.
152	  async function handleDragEnd(groupKey: string, event: DragEndEvent) {
153	    const { active, over } = event;
154	    if (!over || active.id === over.id) return;
155	    const groupItems = items.filter((i) => i.group_key === groupKey).slice().sort(sortInGroup);
156	    const oldIdx = groupItems.findIndex((i) => i.id === active.id);
157	    const newIdx = groupItems.findIndex((i) => i.id === over.id);
158	    if (oldIdx < 0 || newIdx < 0) return;
159	
160	    const reordered = arrayMove(groupItems, oldIdx, newIdx);
161	    const nextSort = new Map(reordered.map((it, idx) => [it.id, idx]));
162	    const changed = reordered.filter((it, idx) => it.sort_order !== idx).map((it) => ({ id: it.id, idx: nextSort.get(it.id)! }));
163	
164	    const before = items;
165	    setItems((prev) => prev.map((it) => (nextSort.has(it.id) ? { ...it, sort_order: nextSort.get(it.id)! } : it)));
166	    try {
167	      await Promise.all(changed.map((c) =>
168	        fetch(`${base}/${c.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sort_order: c.idx }) })
169	          .then((r) => { if (!r.ok) throw new Error("reorder failed"); })));
170	      setError(null);
171	    } catch {
172	      setItems(before);
173	      setError("Could not save the new order");
174	    }
175	  }
176	
177	  async function remove(i: CostItem) {
178	    setBusy(true);
179	    const res = await fetch(`${base}/${i.id}`, { method: "DELETE" });
180	    setBusy(false);
181	    if (res.ok) { setItems((prev) => prev.filter((x) => x.id !== i.id)); setConfirmDel(null); }
182	    else { setError((await res.json().catch(() => ({}))).error || "Could not remove"); setConfirmDel(null); }
183	  }
