14	export async function GET(request: Request, { params }: { params: Promise<{ id: string; eventId: string }> }) {
15	  const { userId } = await v2GetUser(request);
16	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
17	  const { id: orgId, eventId } = await params;
18	
19	  const admin = v2AdminClient();
20	  if (!(await isOrgMember(admin, userId, orgId))) return NextResponse.json({ error: "Not a member" }, { status: 403 });
21	
22	  const { data, error } = await admin
23	    .from("v2_cost_items").select(COST_ITEM_SELECT)
24	    .eq("org_id", orgId).eq("event_id", eventId).order("sort_order").order("created_at");
25	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
26	  return NextResponse.json({ items: data || [] });
27	}
