29	export async function POST(request: Request, { params }: { params: Promise<{ id: string; eventId: string }> }) {
30	  const { userId } = await v2GetUser(request);
31	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
32	  const { id: orgId, eventId } = await params;
33	
34	  const admin = v2AdminClient();
35	  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });
36	
37	  let body: Record<string, unknown>;
38	  try {
39	    body = await request.json();
40	  } catch {
41	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
42	  }
43	  const name = typeof body.name === "string" ? body.name.trim() : "";
44	  if (!name) return NextResponse.json({ error: "Name is required" }, { status: 400 });
45	
46	  const { data, error } = await admin
47	    .from("v2_cost_items")
48	    .insert({
49	      org_id: orgId,
50	      event_id: eventId,
51	      name,
52	      amount_cents: Number.isFinite(body.amount_cents as number) ? (body.amount_cents as number) : 0,
53	      category: typeof body.category === "string" ? body.category : null,
54	      included_in_trip_cost: !!body.included_in_trip_cost,
55	      notes: typeof body.notes === "string" ? body.notes.trim() || null : null,
56	      sort_order: Number.isFinite(body.sort_order as number) ? (body.sort_order as number) : 0,
57	      source_type: "manual",
58	      created_by: userId,
59	    })
60	    .select(COST_ITEM_SELECT)
61	    .single();
62	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
63	  return NextResponse.json({ item: data });
64	}
