1	import { NextResponse } from "next/server";
2	import { v2GetUser, v2AdminClient } from "@/lib/v2/supabase";
3	import { isOrgAdmin } from "@/lib/v2/orgs";
4	import { COST_ITEM_SELECT } from "@/lib/v2/cost-items";
5	
6	/** Edit or delete a single cost item (#213). Org admins only. */
7	
8	const EDITABLE = new Set(["name", "amount_cents", "category", "included_in_trip_cost", "linked_option_id", "notes", "sort_order"]);
9	
10	export async function PATCH(request: Request, { params }: { params: Promise<{ id: string; eventId: string; itemId: string }> }) {
11	  const { userId } = await v2GetUser(request);
12	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
13	  const { id: orgId, eventId, itemId } = await params;
14	
15	  const admin = v2AdminClient();
16	  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });
17	
18	  let body: Record<string, unknown>;
19	  try {
20	    body = await request.json();
21	  } catch {
22	    return NextResponse.json({ error: "Invalid body" }, { status: 400 });
23	  }
24	  const patch: Record<string, unknown> = {};
25	  for (const [k, v] of Object.entries(body)) if (EDITABLE.has(k)) patch[k] = v;
26	  if ("name" in patch) {
27	    const n = String(patch.name || "").trim();
28	    if (!n) return NextResponse.json({ error: "Name can't be empty" }, { status: 400 });
29	    patch.name = n;
30	  }
31	  // Reconcile to one bucket: setting an option clears the trip-cost flag.
32	  if (patch.linked_option_id) patch.included_in_trip_cost = false;
33	  if (patch.included_in_trip_cost === true) patch.linked_option_id = null;
34	  if (Object.keys(patch).length === 0) return NextResponse.json({ error: "Nothing to update" }, { status: 400 });
35	  patch.updated_at = new Date().toISOString();
36	
37	  const { data, error } = await admin
38	    .from("v2_cost_items").update(patch)
39	    .eq("id", itemId).eq("org_id", orgId).eq("event_id", eventId)
40	    .select(COST_ITEM_SELECT).single();
41	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
42	  return NextResponse.json({ item: data });
43	}
44	
45	export async function DELETE(request: Request, { params }: { params: Promise<{ id: string; eventId: string; itemId: string }> }) {
46	  const { userId } = await v2GetUser(request);
47	  if (!userId) return NextResponse.json({ error: "Not authenticated" }, { status: 401 });
48	  const { id: orgId, eventId, itemId } = await params;
49	
50	  const admin = v2AdminClient();
51	  if (!(await isOrgAdmin(admin, userId, orgId))) return NextResponse.json({ error: "Admins only" }, { status: 403 });
52	
53	  // Only manual items are deletable here; source-linked items are removed with
54	  // their source (e.g. deleting the contest).
55	  const { data: item } = await admin.from("v2_cost_items").select("source_type").eq("id", itemId).eq("org_id", orgId).maybeSingle();
56	  if (item && item.source_type !== "manual") {
57	    return NextResponse.json({ error: "This cost comes from a contest or other item; remove it there." }, { status: 400 });
58	  }
59	  const { error } = await admin.from("v2_cost_items").delete().eq("id", itemId).eq("org_id", orgId).eq("event_id", eventId);
60	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
61	  return NextResponse.json({ ok: true });
62	}
